class Device {
    protected String brand;
    public Device(String brand) {
        this.brand = brand;
    }
    public void powerOn() {
        System.out.println(brand + " device powered on");
    }
}

class Computer extends Device {
    protected int ramGigabytes;
    public Computer(String brand, int ram) {
        super(brand);
        this.ramGigabytes = ram;
    }
    public void loadOS() {
        powerOn(); // Inherited from Device
        System.out.println("Booting OS with " + ramGigabytes + "GB RAM");
    }
}

class Laptop extends Computer {
    private double weightKg;
    public Laptop(String brand, int ram, double weight) {
        super(brand, ram);
        this.weightKg = weight;
    }
    public void openLid() {
        loadOS(); // Inherited from Computer
        System.out.println("Laptop ready for mobile use (Weight: " + weightKg + "kg)");
    }
}

public class MultilevelDemo {
    public static void main(String[] args) {
        Laptop myLaptop = new Laptop("Dell", 32, 1.4);
        // Cumulative access across all 3 levels
        myLaptop.openLid();
    }
}

