class Vehicle {
    protected String vin;
    protected String model;
    public Vehicle(String vin, String model) {
        this.vin = vin;
        this.model = model;
    }
}

class CommercialTruck extends Vehicle {
    protected double maxWeightTons;
    public CommercialTruck(String vin, String model, double maxWeight) {
        super(vin, model);
        this.maxWeightTons = maxWeight;
    }
}

class RefrigeratedTruck extends CommercialTruck {
    private double targetTemperatureCelsius;
    public RefrigeratedTruck(String vin, String model, double maxWeight, double targetTemp) {
        super(vin, model, maxWeight);
        this.targetTemperatureCelsius = targetTemp;
    }
    public boolean isTemperatureSafe(double currentTemp) {
        return currentTemp <= targetTemperatureCelsius;
    }
    public void inspectTruck(double currentTemp) {
        System.out.println("Cold Chain Truck " + vin + " [" + model + "] Capacity: " + maxWeightTons + "T");
        System.out.println("Temperature Check: Current " + currentTemp + " C is within target of " + targetTemperatureCelsius + " C: " + isTemperatureSafe(currentTemp));
    }
}

public class Main {
    public static void main(String[] args) {
        RefrigeratedTruck rt = new RefrigeratedTruck("VIN-88", "Freightliner", 22.5, 4.0);
        rt.inspectTruck(2.5);
    }
}

