class CloudResource {
    protected String resourceId;
    protected String region;
    public CloudResource(String resourceId, String region) {
        this.resourceId = resourceId;
        this.region = region;
    }
}

class ComputeInstance extends CloudResource {
    protected int vCpuCount;
    protected int ramGb;
    public ComputeInstance(String resourceId, String region, int vCpu, int ram) {
        super(resourceId, region);
        this.vCpuCount = vCpu;
        this.ramGb = ram;
    }
}

class KubernetesNode extends ComputeInstance {
    private int podCapacity;
    private int allocatedPods;
    public KubernetesNode(String resourceId, String region, int vCpu, int ram, int capacity) {
        super(resourceId, region, vCpu, ram);
        this.podCapacity = capacity;
        this.allocatedPods = 30; // Pre-allocated 30 pods for test
    }
    public boolean schedulePod() {
        if (allocatedPods < podCapacity) {
            allocatedPods++;
            System.out.println("Pod scheduled! Allocated: " + allocatedPods + "/" + podCapacity);
            return true;
        }
        return false;
    }
    public void displayStatus() {
        System.out.println("K8s Node " + resourceId + " [" + region + "] " + vCpuCount + " vCPU, " + ramGb + "GB RAM");
        schedulePod();
        System.out.println("Scheduling full: " + (allocatedPods >= podCapacity));
    }
}

public class Main {
    public static void main(String[] args) {
        KubernetesNode node = new KubernetesNode("i-04a2", "us-east-1", 16, 64, 32);
        node.displayStatus();
    }
}
